VACHYA_ID = ([(a, '', 'कर्तृवाच्य', 'कर्ता प्रधान है; क्रिया कर्ता या कर्म के अनुसार, ‘द्वारा’ का प्रयोग नहीं।') for a, b in VACHYA] +
             [(b, '', 'कर्मवाच्य', 'कर्म प्रधान है; कर्ता के साथ ‘द्वारा’ और क्रिया कर्म के अनुसार (‘किया गया’, ‘बनाई गई’)।') for a, b in VACHYA] +
             [(b, '', 'भाववाच्य', 'भाव (क्रिया) प्रधान है; अकर्मक क्रिया, कर्ता के साथ ‘से’, क्रिया सदा पुल्लिंग एकवचन (‘चला नहीं जाता’)।') for a, b in BHAVA])

def g_vachya_why(kit, key, th):
    """C2: identify the voice of a sentence and justify it from its form."""
    def fn(rng, slot):
        s, _, lab, why = rng.choice(VACHYA_ID)
        stem = rng.choice([f'“{s}”\nयह वाक्य किस वाच्य में है? वाक्य की बनावट (कर्ता, कर्म, क्रिया) के आधार पर कारण बताइए।',
                           f'वाच्य पहचानिए और अपने उत्तर का आधार स्पष्ट कीजिए:\n“{s}”'])
        return dict(stem=stem, answer=f'{lab} — {why}', type='short', marks=2,
                    markingKey=f'1 अंक सही वाच्य ({lab}); 1 अंक बनावट पर आधारित कारण: {why}')
    kit.add(key, 'C2', (2, 4), fn, 'short', None, 'vachya_why')


