def g_device(kit, key, th):
    """C2: explain how a named device in a story serves the author's purpose."""
    def fn(rng, slot):
        st, el, dev, eff = rng.choice(DEVICE10)
        stem = rng.choice([f'कहानी ‘{st}’ में {el} — यहाँ लेखक ने कौन-सी तकनीक अपनाई है और इससे लेखक का उद्देश्य कैसे पूरा होता है?',
                           f'‘{st}’ के संदर्भ में स्पष्ट कीजिए: {el} कहानी के संदेश को कैसे मज़बूत बनाता है? लेखक की तकनीक का नाम भी बताइए।'])
        return dict(stem=stem, answer=f'तकनीक: {dev}। प्रभाव: {eff}।', type='explain', marks=3,
                    markingKey=f'1 अंक तकनीक की पहचान ({dev}); 2 अंक उद्देश्य/संदेश से संबंध की व्याख्या: {eff}।')
    kit.add(key, 'C2', (2, 4), fn, 'explain', None, 'lit_device')

    def cmp_(rng, slot):
        a, b = rng.sample(DEVICE10, 2)
        if a[0] == b[0]:
            return None
        return dict(stem=f'‘{a[0]}’ में {a[1]} और ‘{b[0]}’ में {b[1]} — दोनों तकनीकों की तुलना कीजिए और बताइए कि दोनों लेखक अपने-अपने उद्देश्य तक कैसे पहुँचते हैं।',
                    answer=f'‘{a[0]}’ — {a[2]}: {a[3]}। ‘{b[0]}’ — {b[2]}: {b[3]}। समानता: दोनों तकनीकें संदेश को सीधे उपदेश के बिना पाठक तक पहुँचाती हैं।', type='explain', marks=4,
                    markingKey='1-1 अंक प्रत्येक तकनीक की पहचान; 1-1 अंक प्रत्येक के प्रभाव/उद्देश्य की व्याख्या।')
    kit.add(key, 'C3', (3, 5), cmp_, 'explain', None, 'lit_device_cmp')


